42:   // https://docs.microsoft.com/en-us/cpp/c-runtime-library/reference/stat-functions?view=vs-2019,
43:   // we should use struct __stat64 and _wstat64 for 64-bit file size on Windows.
44:   struct __stat64 stat_buf;
45:   auto fileW = utf8_decode(filename);
46:   int rc = _wstat64(fileW.c_str(), &stat_buf);
47: #else
48:   struct stat stat_buf;
49:   int rc = stat(filename.c_str(), &stat_buf);
50: #endif
51:   // errno is a variable defined in errno.h
52:   STD_TORCH_CHECK(
53:       rc == 0, "[Errno ", errno, "] ", strerror(errno), ": '", filename, "'");
54: 
55:   int64_t size = stat_buf.st_size;
