101:     rgb_line[i * 3 + 0] = clamped_cmyk_rgb_convert(k, 255 - c);
102:     rgb_line[i * 3 + 1] = clamped_cmyk_rgb_convert(k, 255 - m);
103:     rgb_line[i * 3 + 2] = clamped_cmyk_rgb_convert(k, 255 - y);
