43: // kernel, so the lookup in aoti_torch_mps_get_kernel_function fails -- as the
44: // legacy visionPipelineState lookup did for unsupported types.
45: const char* metal_type_string(torch::headeronly::ScalarType scalar_type) {
46:   if (scalar_type == torch::headeronly::ScalarType::Float) {
47:     return "float";
48:   }
49:   if (scalar_type == torch::headeronly::ScalarType::Half) {
50:     return "half";
