66: // Trampoline invoked on the MPS stream's queue by aoti_torch_mps_run_command_block.
67: void nms_encode(AOTIMetalKernelFunctionHandle func, void* user_data) {
68:   const auto* launch_args = static_cast<const NmsLaunchArgs*>(user_data);
69:   TORCH_ERROR_CODE_CHECK(aoti_torch_mps_start_encoding(func));
70:   TORCH_ERROR_CODE_CHECK(
71:       aoti_torch_mps_set_arg_tensor(func, 0, launch_args->dets_sorted));
72:   TORCH_ERROR_CODE_CHECK(
73:       aoti_torch_mps_set_arg_tensor(func, 1, launch_args->mask));
