104:       dets.size(1) == 4,
105:       "boxes should have 4 elements in dimension 1, got ",
106:       dets.size(1));
107:   STD_TORCH_CHECK(
108:       scores.dim() == 1, "scores should be a 1d tensor, got ", scores.dim(), "D");
109:   STD_TORCH_CHECK(
110:       dets.size(0) == scores.size(0),
111:       "boxes and scores should have same number of elements in ",
112:       "dimension 0, got ",
113:       dets.size(0),
114:       " and ",
115:       scores.size(0));
