122:       stable_helpers::sort(scores, /*stable=*/true, /*dim=*/0, /*descending=*/true));
123:   auto dets_sorted =
124:       torch::stable::contiguous(stable_helpers::index_select(dets, 0, order_t));
125:   int64_t dets_num = dets.size(0);
