138:   const std::string kernel =
139:       "nms_" + std::string(metal_type_string(dets_sorted.scalar_type()));
140:   AOTIMetalKernelFunctionHandle func = nullptr;
141:   TORCH_ERROR_CODE_CHECK(aoti_torch_mps_get_kernel_function(
142:       nms_shader_library(), kernel.c_str(), &func));
